 * board of four is four different corrections, and the log should say
 * which of them it was.
 */
const nudgeCounter = useCallback(
  (counter: string, by: number, contestant?: string) => {
    const at = now();
    const label = pack.counters?.[counter]?.label ?? counter;
    const who = contestant ? state?.contestants.find((c) => c.id === contestant)?.name : undefined;
    commit([
      { t: "Corrected", at, note: `${who ? `${who}: ` : ""}${label} ${by > 0 ? "+" : ""}${by}` },
      { t: "CounterChanged", at, counter, by, ...(contestant ? { contestant } : {}) },
    ]);
  },
  [commit, pack, state],
);

/**
 * Turn a dial.
 *
 * Not a correction the way a nudged counter is. A counter is a tally
 * of what happened, so moving it by hand says the tally was wrong; a
 * resource is a setting, and turning it up mid-run is the run being
 * played, not repaired. So no `Corrected` marker above it.
 */
const turnResource = useCallback(
  (resource: string, by: number) => {
    const def = pack.resources?.[resource];
    if (!def) return;
    const at = now();
    const current = state?.resources[resource] ?? def.initial;
    const next = Math.max(def.min ?? 0, Math.min(def.max ?? Infinity, current + by));
    if (next === current) return;
    commit([{ t: "ResourceChanged", at, resource, by: next - current }]);
  },
  [commit, pack, state],
);

/** Counter thresholds that have come due and not yet fired. */
const thresholds = useMemo(() => (state ? pendingTriggers(pack, state) : []), [pack, state]);

const fireThreshold = useCallback(
  (t: { counter: string; index: number; key: string; label: string }) =>
    begin({
      kind: "counterTrigger",
      trigger: { counter: t.counter, index: t.index, key: t.key },
      keyPrefix: t.key,
      label: t.label,
    }),
  [begin],
);

