37	export interface OfferInput {
38	  /** The snapshot this offer belongs to; a press carries it back. */
39	  seq: number;
40	  /** Active, editable, and actually started. */
41	  live: boolean;
42	  /** Nothing more is being asked of this step. */
43	  settled: boolean;
44	  /** The step's own receipts are waiting to be read, and nothing more is asked. */
45	  receipts: boolean;
46	  step: Step | null;
47	  stepLabel: string | null;
48	  /** What the engine is waiting on, when it is waiting on anything at all. */
49	  request: { kind: "roll"; label: string } | { kind: "other" } | null;
50	  moves: Array<{ id: string; label: string }>;
51	  canUndo: boolean;
52	  lastResult: string | null;
53	  /** Obligations standing in the way. */
