59	  /**
60	   * What the step's own button says once every box is ticked, or null
61	   * where the step has no list. The preset presses that button, so it is
62	   * offered in the words the page uses for it.
63	   */
64	  finishLabel: string | null;
65	  /**
66	   * The setups this run could hand out, in the words the picker uses.
67	   *
68	   * Worked out by the page rather than here: a setup is written against
69	   * the tool a run is talking to, and finding those means reading the
70	   * shipped profiles and the shelf, neither of which this function has.
71	   */
72	  setups: Array<{ id: string; title: string }>;
