80	  /** The clock the page's own buttons act on, or null while none is. */
81	  clock: Offer["clock"];
82	  /** Whether this device is throwing the dice for the player. */
83	  autoRoll: boolean;
84	  /** What the page's Finish button says, where the page is showing one. */
85	  ending: Offer["ending"];
86	}
87	
88	/**
89	 * Steps a key can answer with one press, because they ask nothing first.
90	 *
91	 * A step that closes the unit is not listed here: it is routed by
92	 * `closesUnit` below, the same way whichever kind it is, rather than by
93	 * its own kind.
94	 */
95	const PRESSABLE: Record<string, "roll" | "carry-on" | "close" | "enter"> = {
96	  rollTable: "roll",
97	};
98	
