100	const TYPED = new Set(["declareSubject"]);
101	
102	export function offerOf(input: OfferInput): Offer {
103	  const moves = input.moves;
104	  const undo = input.canUndo && input.lastResult ? { what: input.lastResult } : null;
105	  const bare = {
106	    seq: input.seq,
107	    moves,
108	    undo,
109	    presets: [] as Offer["presets"],
110	    setups: input.setups,
111	    trackers: input.trackers,
112	    clock: input.clock,
113	    autoRoll: input.autoRoll,
114	    ending: input.ending,
115	  };
116	
117	  // A run nobody is playing -- not started, read-only, ended -- offers
118	  // nothing at all, moves and undo included. They used to ride out on
119	  // `bare`, and `takePress` reads only those two fields when it takes a
120	  // move or an undo, so a deck could move a run the page itself would not
121	  // let anyone touch. The setups go with them: what a finished run was
122	  // played under is a record of what happened, and a key that could
123	  // rewrite it from another room is worse than no key.
124	  //
125	  // The dials, the clock, the dice setting and the ending are held back for
126	  // the same reason, and held back rather than merely refused: a key face
127	  // drawn from an offer should go dim on a run nobody is playing rather
128	  // than show a tally somebody can press and be told no.
129	  if (!input.live)
130	    return {
131	      ...bare,
132	      moves: [],
133	      undo: null,
134	      setups: [],
135	      trackers: [],
136	      clock: null,
137	      autoRoll: false,
138	      ending: null,
139	      primary: null,
140	      needsPage: "Open the run on the page",
141	    };
142	
143	  // The receipts of the step's own throws sit on the page, waiting to be
144	  // read, before anything about the step itself -- what it is, whether it
145	  // closes the unit -- comes into it. No presets: the checklist and the
146	  // between-units button are both still behind this same screen.
147	  if (input.receipts) return { ...bare, primary: { id: "carry-on", label: "Carry on", kind: "receipt" }, needsPage: null };
148	
149	  if (!input.step) {
150	    if (input.between) return { ...bare, primary: { id: "enter", label: input.between, kind: "between" }, needsPage: null };
151	    return { ...bare, primary: null, needsPage: null };
152	  }
153	
154	  const step = input.step;
155	  const kind = step.kind;
156	  const label = input.stepLabel ?? "";
157	
158	  // An unsettled step is still being asked something, the same reasoning
159	  // `closesTheUnit` uses to refuse an unsettled unit: it is not yet a bare
160	  // press for a key to make. A pending roll is the one exception: nobody is
161	  // being asked to judge anything, only to throw dice, and a deck can throw
162	  // them the same way the page's own "Roll for me" does.
163	  if (!input.settled) {
164	    if (input.request?.kind === "roll")
165	      return { ...bare, primary: { id: "roll", label: input.request.label, kind: "rollTable" }, needsPage: null };
166	    return { ...bare, primary: null, needsPage: `${label} on the page` };
167	  }
168	
169	  if (TYPED.has(kind))
170	    return {
171	      ...bare,
172	      primary: null,
173	      needsPage: `${label} on the page`,
174	      presets: [{ kind, label, ...(input.suggestions.length > 0 ? { suggestions: input.suggestions } : {}) }],
175	    };
176	
177	  // Owed blocks every bare press but a typed step's own preset: the page
178	  // would refuse the same close or carry-on until it is settled, checked
179	  // once here rather than separately for every kind that reaches this far.
180	  if (input.owed > 0) return { ...bare, primary: null, needsPage: "Something is owed; settle it on the page" };
181	
182	  /*
183	   * Ticking the whole list and pressing the step's own button, for a key
184	   * the streamer put there themselves.
185	   *
186	   * A preset, never the primary: `needsPage` stays, so the follow key goes
187	   * on saying the list is on the page. Pressing this one skips the reading,
188	   * which is a decision, and `handsFree.ts` gives the rule -- a decision is
189	   * skipped only where somebody chose to skip it.
190	   *
191	   * The count is what the step waits for, which is its points less the
192	   * optional ones. Not less the ones with nothing to show: that needs the
193	   * log and the pack, and this says what is on offer from the step alone.
194	   */
195	  const list = checklistOf(step);
196	  const ticking: Offer["presets"] =
197	    list.length > 0 && input.finishLabel
198	      ? [
199	          {
200	            kind: "checklist",
201	            label: `Tick everything and ${input.finishLabel}`,
202	            items: list.map(pointOf).filter((p) => !p.optional).length,
203	          },
204	        ]
205	      : [];
206	
207	  // A step that closes the unit goes to the page's closing card, whichever
208	  // kind it is underneath: a finalizeUnit, or a manual step marked
209	  // closesUnit. Its own confirmation or checklist is the same kind of ask
210	  // as any other and sends it back to the page; empty, it is the one
211	  // press that writes the close, not a step's own carry-on.
212	  if (closesUnit(step)) {
213	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
214	    return { ...bare, primary: { id: "close", label, kind: step.kind }, needsPage: null };
215	  }
216	
217	  // A manual step that does not close the unit asks nothing on its own; it
218	  // only asks something when it carries a checklist to confirm. Empty, it
219	  // is as bare a press as a roll.
220	  if (step.kind === "manual") {
221	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
222	    return { ...bare, primary: { id: "carry-on", label, kind }, needsPage: null };
223	  }
224	
225	  const id = PRESSABLE[kind];
226	  if (!id) return { ...bare, primary: null, needsPage: `${label} on the page` };
227	  return { ...bare, primary: { id, label, kind }, needsPage: null };
228	}
